function useUserData(user) {
  const [profile,setProfile]=useStoredState(userKey(user.id,'profile'), {type:'object',shape:{displayName:{type:'string'},age:{type:'number',nullable:true},sex:{type:'string'},weightKg:{type:'number',nullable:true},heightCm:{type:'number',nullable:true},wakeTime:{type:'string'},sleepTime:{type:'string'}}}, defaultProfile);
  const [assessment,setAssessment]=useStoredState(userKey(user.id,'assessment'), {type:'object',shape:{activityLevel:{type:'string'},exerciseDaysPerWeek:{type:'number'},exerciseIntensity:{type:'string'},sweatingLevel:{type:'string'},hotEnvironment:{type:'string'},pregnancyStatus:{type:'string'},conditions:{type:'array',of:{type:'string'}},hasPrescribedTarget:{type:'boolean'},prescribedMl:{type:'number',nullable:true},prescribedNote:{type:'string'},monitoring:{type:'object',shape:{urineColor:{type:'boolean'},symptoms:{type:'boolean'}}},completedAt:{type:'string',nullable:true}}}, defaultAssessment);
  const [penguin,setPenguin]=useStoredState(userKey(user.id,'penguin'), {type:'object',shape:{name:{type:'string'},mood:{type:'string'},xp:{type:'number'},level:{type:'number'},coins:{type:'number'},streak:{type:'number'},accessories:{type:'object',shape:{owned:{type:'array',of:{type:'string'}},equipped:{type:'array',of:{type:'string'}}}},createdAt:{type:'string',nullable:true}}}, defaultPenguin);
  const [onboarding,setOnboarding]=useStoredState(userKey(user.id,'onboarding'),{type:'object',shape:{personal:{type:'boolean'},assessment:{type:'boolean'},penguin:{type:'boolean'}}},defaultOnboarding);
  const [data,setData]=useState(()=>read(userKey(user.id,'appdata'),defaults));
  useEffect(()=>write(userKey(user.id,'appdata'),data),[data,user.id]);
  const patch=(k,v)=>setData(p=>({...p,[k]:typeof v==='function'?v(p[k]):v}));
  const todayKey = new Date().toLocaleDateString('en-CA');
  const todayTotal = (data.logs || []).filter(x => x.date === todayKey).reduce((sum,x) => sum + (Number(x.ml) || 0), 0);
  const hydrationMood = !data.target ? 'neutral' : todayTotal === 0 ? 'thirsty' : todayTotal >= data.target ? 'happy' : 'neutral';
  const companion = { ...penguin, mood: hydrationMood };
  return {profile,setProfile,assessment,setAssessment,penguin:companion,setPenguin,onboarding,setOnboarding,data,patch};
}
